function modal(title,body){const t=$('#modalTemplate').content.cloneNode(true),m=t.querySelector('.modal-backdrop');m.querySelector('h3').textContent=title;m.querySelector('.modal-body').innerHTML=body;m.querySelector('.modal-actions').innerHTML='<button class="btn close-modal">Cancel</button><button class="btn primary modal-save">Save</button>';m.querySelectorAll('.close-modal').forEach(b=>b.onclick=()=>m.remove());document.body.appendChild(m);return m}
function vals(m){const o={};m.querySelectorAll('[name]').forEach(x=>{if(x.type==='checkbox')o[x.name]=x.checked;else if(x.type==='number')o[x.name]=x.value===''?'':+x.value;else o[x.name]=x.value});return o}
function options(list,current){return list.map(s=>`<option ${current===s?'selected':''}>${esc(s)}</option>`).join('')}
function streamOptions(current,includeProgram=true){return `${includeProgram?`<option ${current==='Program'?'selected':''}>Program</option>`:''}${allStreams().map(s=>`<option value="${s.id}" ${current===s.id?'selected':''}>${s.id} · ${esc(s.name)}</option>`).join('')}`}
function editProcess(){const p=(data().subprocesses?.[selectedStream]||[]).find(x=>x.flowId===selectedFlowId);if(!p)return;const g=p.gates||{};const m=modal('Edit / validate As-Is process',`<div class="form-grid"><label>ID<input name="id" value="${esc(p.id)}"></label><label>Status<select name="status">${options(['Draft As-Is','BPO Review','SME Validated','Approved As-Is'],p.status)}</select></label><label class="full">Process name<input name="name" value="${esc(p.name)}"></label><label>Process owner<input name="processOwner" value="${esc(p.processOwner||'')}"></label><label>Business criticality<select name="criticality">${options(['Critical','High','Medium','Low'],p.criticality||'Medium')}</select></label><label class="full">Validation notes<textarea name="validationNotes" rows="3">${esc(p.validationNotes||'')}</textarea></label></div><div class="section-title"><h2>As-Is validation gate</h2><span>complete before approval</span></div><div class="gate-editor">${PROCESS_GATES.map(([k,l])=>`<label class="gate-check"><input type="checkbox" data-gate="${k}" ${g[k]?'checked':''}><span>${esc(l)}</span></label>`).join('')}</div>`);m.querySelector('.modal-save').onclick=()=>{const v=vals(m);Object.assign(p,v);p.gates={};m.querySelectorAll('[data-gate]').forEach(x=>p.gates[x.dataset.gate]=x.checked);if(p.status==='Approved As-Is')PROCESS_GATES.forEach(([k])=>p.gates[k]=true);mark('processes');m.remove();render()}}
function editNode(id){const f=flowFor(selectedFlowId),n=f?.nodes.find(x=>x.id===id);if(!n)return;const m=modal('Document process step',`<div class="form-grid"><label class="full">Activity<input name="label" value="${esc(n.label)}"></label><label>System<input name="system" value="${esc(n.system||'')}"></label><label>Type<select name="type">${options(['activity','decision','milestone'],n.type||'activity')}</select></label><label>Owner / role<input name="owner" value="${esc(n.owner||'')}"></label><label>Department / swimlane<input name="department" value="${esc(n.department||'')}"></label><label>Execution mode<select name="mode">${options(['Manual','Semi-automated','Automated'],n.mode||'Manual')}</select></label><label>Control<input name="control" value="${esc(n.control||'')}"></label><label class="full">Notes<textarea name="notes" rows="3">${esc(n.notes||'')}</textarea></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(n,vals(m));f.systems=[...new Set(f.nodes.map(x=>x.system).filter(Boolean))].sort();markFlow(f);m.remove();render()}}
function editPerson(id,stream=selectedStream){const arr=state.framework.people||=[],x=arr.find(p=>p.id===id),p=x||{id:uid('P'),name:'',role:'SME',stream,capacityPct:25};const m=modal(x?'Edit person':'Add SME',`<div class="form-grid"><label class="full">Name<input name="name" value="${esc(p.name)}"></label><label>Role<select name="role">${options(['BPO','SME','Cross-functional BPO'],p.role||'SME')}</select></label><label>Value stream<select name="stream">${streamOptions(p.stream,false)}</select></label><label>Department<input name="department" value="${esc(p.department||'')}"></label><label>Project capacity %<input type="number" min="0" max="100" name="capacityPct" value="${p.capacityPct||0}"></label><label>Backup<input name="backup" value="${esc(p.backup||'')}"></label><label class="full">Role / responsibilities notes<textarea name="roleNotes" rows="3">${esc(p.roleNotes||'')}</textarea></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(p,vals(m));if(!x)arr.push(p);mark('framework');m.remove();render()}}
function editTask(id,stream=selectedStream){const arr=state.tasks.tasks||[],x=arr.find(t=>t.id===id),t=x||{id:uid('T'),type:'Activity',title:'',stream,process:'All',owner:'',status:'Not Started',priority:'Medium',progress:0,start:today(),baselineDue:'',forecastDue:'',phase:'Current State',dependency:''};const m=modal(x?'Edit task / deliverable':'Add task / deliverable',`<div class="form-grid"><label>Type<select name="type">${options(['Activity','Deliverable','Milestone','Workshop','Approval'],t.type||'Activity')}</select></label><label>Stream<select name="stream">${streamOptions(t.stream)}</select></label><label class="full">Task / deliverable<input name="title" value="${esc(t.title)}"></label><label>Process<input name="process" value="${esc(t.process||'All')}"></label><label>Owner<input name="owner" value="${esc(t.owner)}"></label><label>Approver<input name="approver" value="${esc(t.approver||'')}"></label><label>Priority<select name="priority">${options(['Critical','High','Medium','Low'],t.priority||'Medium')}</select></label><label>Status<select name="status">${options(['Not Started','In Progress','Waiting','Blocked','Ready for Review','BPO Review','Approved','Closed'],t.status||'Not Started')}</select></label><label>Progress %<input type="number" min="0" max="100" name="progress" value="${taskProgress(t)}"></label><label>Phase<input name="phase" value="${esc(t.phase||'')}"></label><label>Start<input type="date" name="start" value="${esc(t.start||'')}"></label><label>Baseline due<input type="date" name="baselineDue" value="${esc(t.baselineDue||t.due||'')}"></label><label>Forecast due<input type="date" name="forecastDue" value="${esc(t.forecastDue||t.due||'')}"></label><label class="full">Dependency<input name="dependency" value="${esc(t.dependency||'')}"></label><label class="full">Blocker / notes<textarea name="blocker" rows="3">${esc(t.blocker||'')}</textarea></label></div>`);m.querySelector('.modal-save').onclick=()=>{const v=vals(m);Object.assign(t,v);t.due=t.baselineDue||t.forecastDue||'';if(!x)arr.push(t);mark('tasks');m.remove();render()}}
function editPain(id,kind='Pain point'){const key=kind==='Opportunity'?'opportunities':'painPoints',arr=vreg(key),x=arr.find(z=>z.id===id),p=x||{id:uid(kind==='Opportunity'?'OPP':'PP'),stream:selectedStream,subprocess:'',title:'',impact:'To assess',phase:'To assess',status:'Open'};const m=modal(x?'Edit item':'Add issue / opportunity',`<div class="form-grid"><label>Type<select name="kind">${options(['Pain point','Opportunity'],kind)}</select></label><label>Stream<select name="stream">${streamOptions(p.stream)}</select></label><label class="full">Process / legacy subprocess<input name="subprocess" value="${esc(p.subprocess)}"></label><label class="full">Description<textarea name="title" rows="4">${esc(p.title)}</textarea></label><label>Impact<select name="impact">${options(['Critical','High','Medium','Low','Quick win','To assess'],p.impact||'To assess')}</select></label><label>Phasing<select name="phase">${options(['Pre ERP','Confirm project scope','Expected ERP gain','Post ERP','To assess'],p.phase||'To assess')}</select></label><label>Owner<input name="owner" value="${esc(p.owner||'')}"></label><label>Status<select name="status">${options(['Open','In Review','Converted to Requirement','Closed'],p.status||'Open')}</select></label><label class="full">Root cause / notes<textarea name="rootCause" rows="3">${esc(p.rootCause||'')}</textarea></label></div>`);m.querySelector('.modal-save').onclick=()=>{const v=vals(m),newKey=v.kind==='Opportunity'?'opportunities':'painPoints';delete v.kind;if(x&&newKey!==key){state.registers[key]=vreg(key).filter(z=>z.id!==x.id);vreg(newKey).push(p)}Object.assign(p,v);if(!x)vreg(newKey).push(p);mark('registers');m.remove();render()}}
function editRequirement(id){const arr=vreg('requirements'),x=arr.find(r=>r.id===id),r=x||{id:uid('REQ'),stream:selectedStream,title:'',type:'Functional',priority:'Must',painPoint:'',fitGap:'TBD',owner:allStreams().find(s=>s.id===selectedStream)?.bpo||'',status:'Draft',testStatus:'Not Started'};const m=modal(x?'Edit requirement':'Add requirement',`<div class="form-grid"><label>ID<input name="id" value="${esc(r.id)}"></label><label>Stream<select name="stream">${streamOptions(r.stream)}</select></label><label>Type<select name="type">${options(['Functional','Control','Reporting','Data','Integration','Non-functional'],r.type||'Functional')}</select></label><label>Priority (MoSCoW)<select name="priority">${options(['Must','Should','Could','Won\'t'],r.priority||'Must')}</select></label><label class="full">Requirement<textarea name="title" rows="3">${esc(r.title)}</textarea></label><label class="full">Business rationale<textarea name="businessRationale" rows="3">${esc(r.businessRationale||'')}</textarea></label><label class="full">Acceptance criteria<textarea name="acceptanceCriteria" rows="3">${esc(r.acceptanceCriteria||'')}</textarea></label><label>Pain point<select name="painPoint"><option value="">—</option>${vreg('painPoints').filter(p=>p.stream===r.stream||p.stream==='ALL').map(p=>`<option value="${p.id}" ${r.painPoint===p.id?'selected':''}>${esc(p.id)}</option>`).join('')}</select></label><label>Owner<input name="owner" value="${esc(r.owner)}"></label><label>D365 capability<input name="d365Capability" value="${esc(r.d365Capability||'')}"></label><label>Fit / Gap<select name="fitGap">${options(['TBD','Fit','Fit with configuration','Process change','Extension','Integration','Reporting / Analytics','Deferred'],r.fitGap||'TBD')}</select></label><label class="full">To-Be design / process<textarea name="toBeDesign" rows="3">${esc(r.toBeDesign||'')}</textarea></label><label>Test status<select name="testStatus">${options(['Not Started','Scenario Defined','Ready','In Progress','Passed','Failed'],r.testStatus||'Not Started')}</select></label><label>Status<select name="status">${options(['Draft','In Review','Approved','Ready for Design','Deferred','Closed'],r.status||'Draft')}</select></label><label class="full">Customization / extension justification<textarea name="customJustification" rows="3">${esc(r.customJustification||'')}</textarea></label><label class="full">Standard alternative considered<textarea name="alternativeConsidered" rows="3">${esc(r.alternativeConsidered||'')}</textarea></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(r,vals(m));if(!x)arr.push(r);mark('registers');m.remove();render()}}
